import{_ as r,o as t,c as a,ag as o}from"./chunks/framework.DzGOF12C.js";const f=JSON.parse('{"title":"Watermark·FIFO 구현 교차검증 (김도균·고보민·이지원)","description":"","frontmatter":{},"headers":[{"level":2,"title":"Watermark (High/Low)","slug":"watermark-high-low","link":"#watermark-high-low","children":[]},{"level":2,"title":"FIFO","slug":"fifo","link":"#fifo","children":[]}],"relativePath":"computer/Research/URA/results/05 GC 정책 교차검증 (3인 비교).md","filePath":"computer/Research/URA/results/05 GC 정책 교차검증 (3인 비교).md"}'),i={name:"computer/Research/URA/results/05 GC 정책 교차검증 (3인 비교).md"};function l(s,e,h,_,n,c){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="watermark·fifo-구현-교차검증-김도균·고보민·이지원" tabindex="-1">Watermark·FIFO 구현 교차검증 (김도균·고보민·이지원) <a class="header-anchor" href="#watermark·fifo-구현-교차검증-김도균·고보민·이지원" aria-label="Permalink to &quot;Watermark·FIFO 구현 교차검증 (김도균·고보민·이지원)&quot;">​</a></h1><p>동일한 실험 목표를 서로 다른 코드 구현으로 진행했을 때, 결과 경향이 일치하는지를 비교해 정책 자체의 효과인지 구현 디테일의 효과인지를 검증.</p><h2 id="watermark-high-low" tabindex="-1">Watermark (High/Low) <a class="header-anchor" href="#watermark-high-low" aria-label="Permalink to &quot;Watermark (High/Low)&quot;">​</a></h2><p><strong>구현 방식 차이</strong></p><ul><li>김도균/고보민: free line이 low를 넘어서도 조금씩 GC를 돌리지 않고, high까지 확 떨어질 때까지 기다렸다가 한 번에 low까지 몰아서 GC</li><li>이지원: 기본 구조는 바꾸지 않고, 대신 hot/cold 데이터 분리를 추가해서 실험</li></ul><p><strong>결과 경향</strong></p><ul><li>김도균/고보민: low 값을 낮게 잡으면 GC가 자주 조금씩, 높게 잡으면 드물게 크게 몰아서 일어남</li><li>이지원: hot/cold의 경우 low↔high를 오가는 스파이크 관찰. seq 워크로드에서는 low에서 high까지 아예 도달하지 못하는 현상도 확인됨</li></ul><p><strong>이 실험의 의미</strong>: 구현 방식이 서로 달라도, watermark가 의도한 대로 GC를 몰아서 처리하는 패턴은 세 명 모두에게서 확인됨 — low/high 사이를 오가며 필요할 때만 몰아서 도는 동작이 구현 디테일에 크게 좌우되지 않고 안정적으로 재현됨.</p><h2 id="fifo" tabindex="-1">FIFO <a class="header-anchor" href="#fifo" aria-label="Permalink to &quot;FIFO&quot;">​</a></h2><p><strong>구현 방식 차이</strong></p><ul><li>고보민, 이지원: write_seq 관리용 새 큐 자료구조를 별도로 구현</li><li>김도균: 기존 priority queue의 정렬 기준을 vpc → write_seq로 교체 (자료구조 추가 없이 정렬 기준만 변경)</li></ul><p><strong>결과 경향</strong>: 세부적인 수치까지 동일하지는 않지만 유사한 경향 관찰 — 순차 write에서는 greedy·FIFO 차이가 없고, 랜덤 write에서는 FIFO 쪽에서 GC 횟수 증가 + tail latency가 튀는 패턴이 공통적으로 관찰됨 (본인 실험 결과인 <a href="./02 virt_fifo_GC (Greedy vs FIFO) 실험 결과.html">02 virt_fifo_GC (Greedy vs FIFO) 실험 결과</a>와 동일한 경향).</p><p><strong>이 실험의 의미</strong>: 구현 방식이 서로 달라도 정책 로직만 같으면 세 명 모두 같은 경향의 결과가 나옴 — FIFO 정책의 특성이 구현 디테일보다 정책 자체에 의해 결정된다는 것을 세 개의 독립적인 구현으로 교차검증함.</p>',13)])])}const m=r(i,[["render",l]]);export{f as __pageData,m as default};
